function plural(count, one, many) {
  return `${count} ${count === 1 ? one : many}`;
}
async function updateOrgFromExcel() {
  if (!openMap || openKind !== "org") return;
  try {
    const file = await window.api.pickImportFile();
    if (!file) return;
    const { org, changes } = await outlineFromFile(file, orgView.getData());
    if (changes.added + changes.removed + changes.changed === 0) {
      showToast("A planilha é igual ao organograma: nada para atualizar.");
      return;
    }
    const summary = [
      plural(changes.added, "caixa nova", "caixas novas"),
      plural(changes.removed, "removida", "removidas"),
      plural(changes.changed, "alterada", "alteradas")
    ].join(", ");
    const confirmed = await confirmAction({
      title: "Atualizar pelo Excel",
      message: `A planilha traz ${summary}. Dá para desfazer com Ctrl+Z.`,
      confirmLabel: "Atualizar"
    });
    if (!confirmed) return;
    orgView.replaceData(org);
    showToast("Organograma atualizado pela planilha.");
  } catch (error) {
    showError(error);
  }
}
async function exportOrgPdf() {
  if (!openMap || openKind !== "org") return;
  try {
    const html2 = orgView.exportPdfHtml(openMap.meta.title);
    const saved = await window.api.exportPdf(openMap.meta.title, html2);
    if (saved) showToast('PDF pronto: escolha "Salvar como PDF" na janela de impressão.');
  } catch (error) {
    showError(error);
  }
}
// PDF da prancheta: a folha sai do mesmo envelope do SVG/PNG (sem a guia de trabalho).
async function exportDrawPdf() {
  if (!openMap || openKind !== "draw") return;
  try {
    const saved = await window.api.exportPdf(openMap.meta.title, buildDrawPdfHtml(openMap.meta.title, stage.sketch().document));
    if (saved) showToast('PDF pronto: escolha "Salvar como PDF" na janela de impressão.');
  } catch (error) {
    showError(error);
  }
}
async function exportCurrent(kind) {
  if (!openMap) return;
  try {
    const saved = await window.api.saveExport(kind, openMap.meta.title, await exportData(kind));
    if (saved) showToast(`Exportado como ${EXPORT_LABELS[kind]}.`);
  } catch (error) {
    showError(error);
  }
}
async function importMap() {
  try {
    const file = await window.api.pickImportFile();
    if (!file) return;
    const imported = await importFromFile(file);
    if ("drawing" in imported) {
      await sidebar.importIntoTarget(imported.title, "desenho", imported.drawing);
    } else if ("org" in imported) {
      await sidebar.importIntoTarget(imported.title, "organograma", imported.org);
    } else if ("mindmap" in imported) {
      await sidebar.importIntoTarget(imported.title, "livre", imported.mindmap);
    } else {
      await sidebar.importIntoTarget(imported.title, "livre", imported.tree);
    }
  } catch (error) {
    showError(error);
  }
}
async function openHistory() {
  if (!openMap) return;
  const { path } = openMap;
  try {
    if (!await flushSafely()) return;
    const versions = await window.api.listVersions(path);
    if (versions.length === 0) {
      showToast("Este mapa ainda não tem versões anteriores. Elas são criadas conforme você edita.");
      return;
    }
    const versionId = await chooseVersion(versions);
    if (!versionId) return;
    autosave.reset();
    await window.api.restoreVersion(path, versionId);
    await openMapAt(path, { force: true });
    showToast("Versão restaurada.");
  } catch (error) {
    showError(error);
  }
}
function openSearch() {
  if (!openMap || openKind !== "mindmap") return;
  byId("search-bar").hidden = false;
  setPressed("btn-search", true);
  const input = byId("search-input");
  input.focus();
  input.select();
}
function closeSearch() {
  byId("search-bar").hidden = true;
  setPressed("btn-search", false);
  editor.endSearch();
}
function runSearch() {
  const text = byId("search-input").value;
  if (text) editor.search(text);
  else editor.endSearch();
}
async function startWorkspace() {
  try {
    await sidebar.refresh();
  } catch (error) {
    showError(error);
  }
}
function bindToolbar() {
  byId("btn-new-map").addEventListener(
    "click",
    () => void sidebar.createMapInTarget().catch(showError)
  );
  byId("btn-new-folder").addEventListener(
    "click",
    () => void sidebar.createFolderInTarget().catch(showError)
  );
  byId("btn-import").addEventListener("click", () => void importMap());
  layoutSelect.addEventListener("change", () => editor.setLayout(layoutSelect.value));
  byId("btn-minimap").addEventListener("click", () => minimap.toggle());
  byId("btn-history").addEventListener("click", () => void openHistory());
  byId("btn-logout").addEventListener("click", () => void logout());
  byId("btn-save").addEventListener("click", () => void flushSafely());
  byId("btn-search").addEventListener("click", openSearch);
  byId("btn-fit").addEventListener(
    "click",
    () => openKind === "org" ? orgView.fit() : openKind === "draw" ? stage.fitPaper() : editor.fit()
  );
  byId("btn-org-orient").addEventListener("click", () => orgView.toggleOrientation());
  byId("btn-org-undo").addEventListener("click", () => orgView.undo());
  byId("btn-org-redo").addEventListener("click", () => orgView.redo());
  byId("btn-export-svg").addEventListener("click", () => void exportCurrent("svg"));
  byId("btn-export-csv").addEventListener("click", () => void exportCurrent("csv"));
  byId("btn-export-pdf").addEventListener("click", () => void (openKind === "draw" ? exportDrawPdf() : exportOrgPdf()));
  byId("btn-export-xlsx").addEventListener("click", () => void exportCurrent("xlsx"));
  byId("btn-export-share").addEventListener("click", () => void exportCurrent("swmap"));
  byId("btn-update-xlsx").addEventListener("click", () => void updateOrgFromExcel());
  byId("btn-note").addEventListener("click", () => {
    notePanel.toggle();
    editor.resize();
  });
  byId("btn-export-png").addEventListener("click", () => void exportCurrent("png"));
  byId("btn-export-md").addEventListener("click", () => void exportCurrent("md"));
  byId("btn-export-pop").addEventListener("click", () => void exportPop());
  byId("btn-copy-pop").addEventListener("click", () => void copyPop());
  byId("btn-theme").addEventListener("click", () => void toggleTheme().catch(showError));
  byId("btn-search-next").addEventListener("click", runSearch);
  byId("btn-search-close").addEventListener("click", closeSearch);
  const searchInput = byId("search-input");
  searchInput.addEventListener("keydown", (event) => {
    if (event.key === "Enter") runSearch();
    if (event.key === "Escape") closeSearch();
  });
  searchInput.addEventListener("input", runSearch);
}
function bindShortcuts() {
  window.addEventListener("keydown", (event) => {
    if (!event.ctrlKey) return;
    const key = event.key.toLowerCase();
    if (key === "s") {
      event.preventDefault();
      void flushSafely();
    } else if (key === "f") {
      event.preventDefault();
      openSearch();
    }
  });
  window.addEventListener("resize", () => {
    editor.resize();
    orgView.resize();
  });
}
function bindWindowClose() {
  window.addEventListener("beforeunload", (event) => {
    const state = statusEl.dataset.state;
    if (state !== "dirty" && state !== "saving" && state !== "error") return;
    void autosave.flush().catch(() => void 0);
    event.preventDefault();
    event.returnValue = "";
  });
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "hidden") void autosave.flush().catch(() => void 0);
  });
}
async function init() {
  // A casca entra de pé antes das idas à nuvem: o overlay #boot sai assim que a sessão está
  // decidida (login ou mapa), não quando o primeiro mapa carrega. O finally cobre os dois
  // caminhos — config resolvido ou getConfig falhando — e o erro que sobe para init().catch
  // já encontra a tela liberada.
  try {
    try {
      config = await window.api.getConfig();
    } catch (error) {
      // Nuvem fora do ar ou bloqueada: mostra a tela de entrada mesmo assim, para dar o que fazer
      // (tentar de novo) em vez de deixar a casca do app sem mapa e sem login.
      showError(error);
      config = { theme: "dark", user: null };
    }
    applyTheme(config.theme);
    initToolbar();
    updateThemeButton();
    bindToolbar();
    bindShortcuts();
    bindWindowClose();
    showMapArea(false);
  } finally {
    document.documentElement.dataset.booted = "1";
  }
  if (config.user) await enterWorkspace(config.user);
  else showLogin();
}
async function enterWorkspace(user) {
  config = { ...config, user };
  sidebar.setUser(user);
  await startWorkspace();
}
function showLogin() {
  const overlay = byId("login");
  const form = byId("login-form");
  const userInput = byId("login-user");
  const passInput = byId("login-pass");
  const error2 = byId("login-error");
  const submit = byId("btn-login");
  userInput.value = "";
  passInput.value = "";
  error2.textContent = "";
  overlay.hidden = false;
  userInput.focus();
  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    if (submit.disabled) return;
    submit.disabled = true;
    error2.textContent = "";
    try {
      const next2 = await window.api.login(userInput.value.trim(), passInput.value);
      config = { theme: next2.theme, user: next2.user };
      applyTheme(config.theme);
      updateThemeButton();
      passInput.value = "";
      overlay.hidden = true;
      await enterWorkspace(config.user);
    } catch (error) {
      error2.textContent = errorMessage(error);
      passInput.select();
    } finally {
      submit.disabled = false;
    }
  });
}
init().catch(showError);
